    (v_route, 'zámek Vranov nad Dyjí', 'Zámek v Česku. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 48.89275, 15.81203, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03%28js%29%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vranov%20nad%20Dyji03%28js%29%20crop.jpg"}'::text[], 0, '{"en": {"name": "Vranov nad Dyjí Castle", "description": "National monument of the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss Vranov nad Dyjí", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek we Vranovie nad Dyji", "description": "Czeski zamek. Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "zámek Vranov nad Dyjí", "description": "Kasteel in Vranov nad Dyjí, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Vranov nad Dyjí Castillo", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Vranov nad Dyjí", "description": "Monument national culturel en Tchéquie. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Вранов-над-Диєю", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'vodní nádrž Vranov', 'Vodní nádrž na Dyji. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.91099, 15.80986, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%C5%99%C3%ADbrn%C3%A1%20z%C3%A1toka%20-%20panoramio%20-%20F.Krikava%2C%20Znojmo%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%C5%99%C3%ADbrn%C3%A1%20z%C3%A1toka%20-%20panoramio%20-%20F.Krikava%2C%20Znojmo%20%281%29.jpg"}'::text[], 1, '{"en": {"name": "Vranov Reservoir", "description": "Reservoir in the Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Frain", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Vranov", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Vranov", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Vranov", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Vranov", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Vranov", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
