    (v_route, 'Plešné jezero', 'Šumavské jezero. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.77639, 13.86528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ple%C5%A1n%C3%A9%20jezero.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ple%C5%A1n%C3%A9%20jezero.jpg"}'::text[], 0, '{"en": {"name": "Plešné jezero", "description": "Lake in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Plešné jezero", "description": "See in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Plešné jezero", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Plešné jezero", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Plešné jezero", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Plešné jezero", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Plešné jezero", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
