    (v_route, 'Rozhledna Diana', 'Rozhledna v Karlových Varech. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.219, 12.8724, 'http://commons.wikimedia.org/wiki/Special:FilePath/Karlovy%20Vary%2C%20horn%C3%AD%20stanice%20lanov%C3%A9%20dr%C3%A1hy%20Diana%20a%20rozhledna.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Karlovy%20Vary%2C%20horn%C3%AD%20stanice%20lanov%C3%A9%20dr%C3%A1hy%20Diana%20a%20rozhledna.jpg"}'::text[], 3, '{"en": {"name": "Rozhledna Diana", "description": "Observation tower. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Diana", "description": "Aussichtsturm bei Karlsbad (Karlovy Vary), Tschechien. Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża widokowa Diana", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Wieża widokowa Diana", "description": "Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rozhledna Diana", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rozhledna Diana", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Rozhledna Diana", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Vyhlídka Karla IV. (rozhledna)', 'Kulturní památka České republiky na území obce Karlovy Vary. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.2161, 12.8803, 'http://commons.wikimedia.org/wiki/Special:FilePath/Karlovy%20Vary%20vyhl%C3%ADdka%20Karla%20IV.%20z%C3%A1%C5%99%C3%AD%202022%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Karlovy%20Vary%20vyhl%C3%ADdka%20Karla%20IV.%20z%C3%A1%C5%99%C3%AD%202022%20%281%29.jpg"}'::text[], 4, '{"en": {"name": "Vyhlidka Karla IV.", "description": "Observation tower in Czech Republic. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Vyhlídka Karla IV.", "description": "Aussichtsturm bei Karlsbad, Tschechien. Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Vyhlídka Karla IV. (rozhledna)", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Vyhlídka Karla IV. (rozhledna)", "description": "Uitkijktoren in Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Vyhlídka Karla IV. (rozhledna)", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "belvédère Charles IV", "description": "Tour d''observation tchèque. Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Vyhlídka Karla IV. (rozhledna)", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Synagoga v Karlových Varech', 'Zaniklá   zděná   synagoga   (známka 600). Památka v Česku — kus historie přímo u trasy.', 50.2258, 12.8781, 'http://commons.wikimedia.org/wiki/Special:FilePath/Syna%20Karlsbad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Syna%20Karlsbad.jpg"}'::text[], 5, '{"en": {"name": "Synagogue in Karlovy Vary", "description": "A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Ehemalige Synagoge in Karlsbad, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Karlowych Warach", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Karlových Varech", "description": "Synagoge in Okres Karlsbad, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Karlových Varech", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Carlsbad", "description": "Ou synagogue de Karlovy Vary, en Tchéquie, inaugurée en 1877, détruite en 1938, lors de la nuit de Cristal. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Karlových Varech", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
