    (v_route, 'Hradec nad Moravicí', 'Zámecký komplex v Hradci nad Moravicí. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.86391, 17.87477, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hradec2%20396388-1382.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hradec2%20396388-1382.jpg"}'::text[], 4, '{"en": {"name": "Hradec nad Moravicí Castle", "description": "National monument of the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss Hradec nad Moravicí", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hradec nad Moravicí", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hradec nad Moravicí", "description": "Kasteel in Hradec nad Moravicí, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Hradec nad Moravicí", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Hradec nad Moravicí", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Градець-над-Моравіцей", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Vodní nádrž Kružberk', 'Vodní nádrž na Moravici. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.82306, 17.6625, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kru%C5%BEberk%20reservoir.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kru%C5%BEberk%20reservoir.jpg"}'::text[], 5, '{"en": {"name": "Údolní nádrž Kružberk", "description": "Reservoir in Kružberk, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Vodní nádrž Kružberk", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zbiornik wodny Kružberk", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Kružberk", "description": "Stuwmeer in Kružberk, Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Kružberk", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Kružberk", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodní nádrž Kružberk", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
