    (v_route, 'Haniperk', 'Rozhledna v okresu Strakonice. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 49.12314, 14.11665, 'http://commons.wikimedia.org/wiki/Special:FilePath/Haniperk%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Haniperk%2002.jpg"}'::text[], 1, '{"en": {"name": "Haniperk", "description": "Observation tower in Strakonice District, Czech Republic. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Haniperk", "description": "Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Haniperk", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Haniperk", "description": "Berg in Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Haniperk", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Haniperk", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Haniperk", "description": "Гора в Чеській Республіці. Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Vodní nádrž Husinec', 'Vodní nádrž v okrese Prachatice. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.03592, 13.98423, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodni%20nadrz%20Husinec.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodni%20nadrz%20Husinec.jpg"}'::text[], 2, '{"en": {"name": "Husinec Reservoir", "description": "Reservoir in Husinec, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Husinec", "description": "Stausee im Bezirk Prachatitz, Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodní nádrž Husinec", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Husinec", "description": "Stuwmeer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Husinec", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Husinec", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodní nádrž Husinec", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Opolenec', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.0867, 13.7975, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sudslavicka%20cave%20in%20nature%20reserve%20Opolenec%20in%20winter%20%281%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sudslavicka%20cave%20in%20nature%20reserve%20Opolenec%20in%20winter%20%281%29.JPG"}'::text[], 3, '{"en": {"name": "Opolenec", "description": "Nature reserve in Prachatice District in the Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Opolenec", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rezerwat przyrody Opolenec", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Opolenec", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Opolenec", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Opolenec", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Opolenec", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
