    (v_route, 'Minaret', 'Rozhledna v Lednici v Lednicko-valtickém areálu. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 48.81415, 16.8126, 'http://commons.wikimedia.org/wiki/Special:FilePath/Minaret%20in%20Lednice%20-%20se%20stromy.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Minaret%20in%20Lednice%20-%20se%20stromy.JPG"}'::text[], 1, '{"en": {"name": "Minaret in Lednice", "description": "Observation tower in Lednice in the Lednice-Valtice area, Czech Republic. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Minarett", "description": "Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Minaret", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Minaret", "description": "Uitkijktoren in Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Minaret", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Minaret", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Minaret", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
