    (v_route, 'Pančavský vodopád', 'Vodopád v Krkonoších. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 50.7612, 15.5461, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pancavsky%20waterfall%202010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pancavsky%20waterfall%202010.jpg"}'::text[], 0, '{"en": {"name": "Pančavský vodopád", "description": "Waterfall in Czechia. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Pantschefall", "description": "Wasserfall in Tschechien. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Wodospad Panczawy", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Pančavský vodopád", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Pančavský vodopád", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Pančavský vodopád", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Pančavský vodopád", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Labský vodopád', 'Vodopád na Labi v Krkonoších. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 50.77091, 15.54874, 'http://commons.wikimedia.org/wiki/Special:FilePath/Elbfall.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Elbfall.jpg"}'::text[], 1, '{"en": {"name": "Labský vodopád", "description": "Waterfall. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Elbfall", "description": "Wasserfall in Tschechien. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Wodospad Łaby", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Labský vodopád", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Labský vodopád", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Labský vodopád", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Labský vodopád", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Mechové jezírko', 'Ledovcové jezírko v Krkonoších. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.7402, 15.5397, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mechov%C3%A9%20jez%C3%ADrko%20nad%20Doln%C3%ADmi%20M%C3%ADse%C4%8Dkami%20v%20Krkono%C5%A1%C3%ADch%20%285%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mechov%C3%A9%20jez%C3%ADrko%20nad%20Doln%C3%ADmi%20M%C3%ADse%C4%8Dkami%20v%20Krkono%C5%A1%C3%ADch%20%285%29.jpg"}'::text[], 2, '{"en": {"name": "Mechové jezírko", "description": "Lake in Vítkovice, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Mechové jezírko", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Mechové jezírko (Karkonosze)", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Mechové jezírko", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Mechové jezírko", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Mechové jezírko", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Mechové jezírko", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'vodní nádrž Souš', 'Přehradní nádrž se sypanou hrází na řece Černá Desná v Desné. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.79626, 15.31349, 'http://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99ehradn%C3%AD%20n%C3%A1dr%C5%BE%20Sou%C5%A1%20ze%20vzduchu3%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99ehradn%C3%AD%20n%C3%A1dr%C5%BE%20Sou%C5%A1%20ze%20vzduchu3%20crop.jpg"}'::text[], 3, '{"en": {"name": "Souš Reservoir", "description": "Reservoir on the Černá Desná in Desná. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Darretalsperre", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Souš", "description": "Zbiornik retencyjny (Desná, Czechy). Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Souš", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Souš", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Souš", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Souš", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'přehrada Desná', 'Bývalé vodní dílo na řece Desné. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.80096, 15.2772, 'http://commons.wikimedia.org/wiki/Special:FilePath/Protr%C5%BEen%C3%A1%20p%C5%99ehrada%2C%20%C5%A1oup%C3%A1tkov%C3%A1%20v%C4%9B%C5%BE%20%2807%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Protr%C5%BEen%C3%A1%20p%C5%99ehrada%2C%20%C5%A1oup%C3%A1tkov%C3%A1%20v%C4%9B%C5%BE%20%2807%29.jpg"}'::text[], 4, '{"en": {"name": "Desná Dam", "description": "Former dam in Albrechtice v Jizerských horách, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre an der Weißen Desse", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "přehrada Desná", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "přehrada Desná", "description": "Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "přehrada Desná", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "přehrada Desná", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "přehrada Desná", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'přehrada Josefův Důl', 'Přehrada vodní nádrže Josefův Důl. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.7946, 15.1955, 'http://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20josefuv%20dul%20hraz.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20josefuv%20dul%20hraz.jpg"}'::text[], 5, '{"en": {"name": "Josefův Důl dam", "description": "Reservoir in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Josefsthal", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "přehrada Josefův Důl", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "přehrada Josefův Důl", "description": "Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "přehrada Josefův Důl", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "přehrada Josefův Důl", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "přehrada Josefův Důl", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Synagoga v Jablonci nad Nisou', 'Zaniklá   zděná   synagoga   (známka 600). Památka v Česku — kus historie přímo u trasy.', 50.72247, 15.17254, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20gablonz-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20gablonz-1.jpg"}'::text[], 6, '{"en": {"name": "Synagogue in Jablonec nad Nisou", "description": "A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge in Jablonec", "description": "Synagoge in Jablonec nad Nisou, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga v Jablonci nad Nisou", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Jablonci nad Nisou", "description": "Synagoge in Okres Jablonec nad Nisou, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Jablonci nad Nisou", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Gablonz an der Neiße", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Jablonci nad Nisou", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'skalní hrad Vranov', 'Též Pantheon, romanticky upravené pozůstatky skalního hradu na Malé Skále. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.64242, 15.18783, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vranov04.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vranov04.jpg"}'::text[], 7, '{"en": {"name": "Vranov Castle", "description": "Rock castle. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Felsenburg Vranov", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Vranov nad Izerą", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Felsenburg Vranov", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "skalní hrad Vranov", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "skalní hrad Vranov", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "skalní hrad Vranov", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb);
