    (v_route, 'Manínska tiesňava', 'Národní přírodní rezervace na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.13979, 18.50747, 'http://commons.wikimedia.org/wiki/Special:FilePath/Maninska%20tiesnava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Maninska%20tiesnava.jpg"}'::text[], 0, '{"en": {"name": "Manínska Gorge", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Manínska tiesňava", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Manínska tiesňava", "description": "Rezerwat przyrody. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Manínska tiesňava", "description": "Natuurgebied in Okres Považská Bystrica, Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Manínská tiesňava", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Gorges de Manínska", "description": "Réserve naturelle nationale de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Манінська ущелина", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Súľov', 'Zřícenina hradu na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 49.17477, 18.5838, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sulovsky%20hrad1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sulovsky%20hrad1.jpg"}'::text[], 1, '{"en": {"name": "Súľovský hrad", "description": "A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Súľov", "description": "Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Súľov", "description": "Zamek obronny na Słowacji. Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Súľov", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Súľov", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Súľov", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Súľov", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Synagoga v Bytči', 'Synagoga a národní kulturní památka, Bytča, okrese Bytča. Památka v Slovensku — kus historie přímo u trasy.', 49.22071, 18.56004, 'http://commons.wikimedia.org/wiki/Special:FilePath/Byt%C4%8Da%20-%20synagogue.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Byt%C4%8Da%20-%20synagogue.jpg"}'::text[], 2, '{"en": {"name": "Synagogue in Bytča", "description": "A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Gebäude in Bytča, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Bytčy", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Bytči", "description": "Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Bytči", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Synagoga v Bytči", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Bytči", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Neologická synagoga v Žilině', 'Synagoga na Slovensku. Památka v Slovensku — kus historie přímo u trasy.', 49.22472, 18.73715, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zilina%20%2814%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zilina%20%2814%29.jpg"}'::text[], 3, '{"en": {"name": "New Synagogue, Žilina", "description": "Synagogue in Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Neologe Synagoge", "description": "Ehemalige Synagoge, später Theater und Kino in Žilina, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Neologiczna Synagoga w Żylinie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Neologická synagoga v Žilině", "description": "Synagoge in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Neologická synagóga", "description": "Antiguo sinagoga, teatro y cine de Žilina, Eslovaquia. Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Neologická synagóga", "description": "Ancienne synagogue, postérieurement théâtre et cinéma à Žilina, Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Neologická synagoga v Žilině", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika Narození Přeblahoslavené Panny Marie', 'Kostel v Rajecké Lesné. Památka v Slovensku — kus historie přímo u trasy.', 49.0439, 18.6353, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bazilka.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bazilka.jpg"}'::text[], 4, '{"en": {"name": "Basilica of Nativity of Virgin Mary", "description": "Church building in Žilina District, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Basilika Mariä Geburt", "description": "Kirche in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Narodzenia Maryi Panny (Rajecká Lesná)", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kľacký vodopád', 'Národní přírodní památka na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.9825, 18.65556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Klacky%20vodopad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Klacky%20vodopad.jpg"}'::text[], 5, '{"en": {"name": "Kľacký vodopád", "description": "National natural monument in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Kľacký vodopád", "description": "Wasserfall in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kľacký vodopád", "description": "Wodospad na Słowacji. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kľacký vodopád", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Klacky vodopad", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Kľacký vodopád", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Kľacký vodopád", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Vodní nádrž Nosice', 'Vodní nádrž na řece Váh. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.15083, 18.38722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Udica%20bay.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Udica%20bay.jpg"}'::text[], 6, '{"en": {"name": "Nosice Reservoir", "description": "A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Nosice", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodní nádrž Nosice", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Nosice", "description": "Stuwmeer in Okres Púchov, Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Nosice", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Nosice", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "ГЕС Носіце", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Vršatecký hrad', 'Zřícenina hradu. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 49.06626, 18.15055, 'http://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%99%C3%ADcenina%20hradu%20Vr%C5%A1atec.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Z%C5%99%C3%ADcenina%20hradu%20Vr%C5%A1atec.jpg"}'::text[], 7, '{"en": {"name": "Vršatec Castle", "description": "Castle ruin. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Löwenstein", "description": "Burgruine in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Vršatecký hrad", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Vršatecký hrad", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Vršatecký hrad", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Vršatecký hrad", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Vršatecký hrad", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb);
