    (v_route, 'Novodvorský močál', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.685, 18.3942, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pansk%C3%A9%20Nov%C3%A9%20Dvory%20-%20Novodvorsk%C3%BD%20mo%C4%8D%C3%A1l%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pansk%C3%A9%20Nov%C3%A9%20Dvory%20-%20Novodvorsk%C3%BD%20mo%C4%8D%C3%A1l%202.jpg"}'::text[], 1, '{"en": {"name": "Novodvorský močál", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Novodvorský močál", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rezerwat przyrody Novodvorský močál", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Novodvorský močál", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Novodvorský močál", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Novodvorský močál", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Новодворське болото", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
