    (v_route, 'Kostel a klášter sv. Kateřiny Alexandrijské', 'Zřícenina kostela a kláštera a národní kulturní památka v obci Dechtice, okrese Trnava, Slovensko. Památka v Slovensku — kus historie přímo u trasy.', 48.5552, 17.53566, 'http://commons.wikimedia.org/wiki/Special:FilePath/Katarinka%202008.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Katarinka%202008.jpg"}'::text[], 5, '{"en": {"name": "Church and monastery of St. Catherine of Alexandria", "description": "Ruins of a church and a monastery and a national cultural monument in the village of Dechtice, Trnava district, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kirche und Kloster St. Katharina von Alexandria", "description": "Kirchen und Klosterruinen und nationales Kulturdenkmal im Dorf Dechtice, Bezirk Trnava, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kostel a klášter sv. Kateřiny Alexandrijské", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kostel a klášter sv. Kateřiny Alexandrijské", "description": "Kerkgebouw in Dechtice, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia y Monasterio de Santa Catalina de Alejandría", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Kostel a klášter sv. Kateřiny Alexandrijské", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kostel a klášter sv. Kateřiny Alexandrijské", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
