    (v_route, 'Kyjovský prales', 'Národní přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.85836, 22.02098, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kyjov%20019.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kyjov%20019.JPG"}'::text[], 7, '{"en": {"name": "Kyjovský prales", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Kyjovský prales", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rezerwat przyrody Kyjovský prales", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kyjovský prales", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Kyjovsky prales", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Kyjovský prales", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Kyjovský prales", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb);
