    (v_route, 'Synagoga v Banské Štiavnici', 'Národní kulturní památka v obci Banská Štiavnica, okrese Banská Štiavnica. Památka v Slovensku — kus historie přímo u trasy.', 48.45822, 18.89337, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20-%20Synag%C3%B3ga%20-a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bansk%C3%A1%20%C5%A0tiavnica%20-%20Synag%C3%B3ga%20-a.jpg"}'::text[], 0, '{"en": {"name": "Synagogue, Banská Štiavnica", "description": "A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Gebäude in Banská Štiavnica, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Bańskiej Szczawnicy", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Banské Štiavnici", "description": "Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Banské Štiavnici", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Banská Štiavnica", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Banské Štiavnici", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
