    (v_route, 'Kláštorisko', 'Planina na stejnojmenném vrcholu Slovenského ráje. Památka v Slovensku — kus historie přímo u trasy.', 48.94455, 20.42159, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1torisko.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1torisko.jpg"}'::text[], 1, '{"en": {"name": "Kláštorisko", "description": "A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kláštorisko", "description": "Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kláštorisko", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kláštorisko", "description": "Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Kláštorisko", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Kláštorisko", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kláštorisko", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Burg Marksdorf', 'Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.91583, 20.6203, 'http://commons.wikimedia.org/wiki/Special:FilePath/Markusovce%20Hrad-02.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Markusovce%20Hrad-02.jpg"}'::text[], 2, '{"en": {"name": "Burg Marksdorf", "description": "Historic site in Slovakia. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Marksdorf", "description": "Ruine im slowakischen Marksdorf. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Burg Marksdorf", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burg Marksdorf", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Burg Marksdorf", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Burg Marksdorf", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Burg Marksdorf", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
