    (v_route, 'Bôrik', 'Přírodní rezervace na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.06361, 20.15361, 'http://commons.wikimedia.org/wiki/Special:FilePath/B%C3%B4rik.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/B%C3%B4rik.jpg"}'::text[], 5, '{"en": {"name": "Bôrik", "description": "Nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Bôrik", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Bôrik", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Bôrik", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Bôrik", "description": "Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Bôrik", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Bôrik", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
