    (v_route, 'Roháčský vodopád', 'Vodopád v Západních Tatrách na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.2136, 19.7289, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rohacsky%20vodopad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rohacsky%20vodopad.jpg"}'::text[], 7, '{"en": {"name": "Roháčsky vodopád", "description": "A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Roháčský vodopád", "description": "Wasserfall in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rohackie Wodospady", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Roháčský vodopád", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Roháčský vodopád", "description": "Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Roháčský vodopád", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Roháčský vodopád", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb);
