    (v_route, 'synagoga v Humpolci', 'Bývalá synagoga, sbor Jana Želivského. Památka v Česku — kus historie přímo u trasy.', 49.5387, 15.3599, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue%20in%20Humpolec.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue%20in%20Humpolec.JPG"}'::text[], 2, '{"en": {"name": "synagogue in Humpolec", "description": "Church building in Humpolec, Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Synagoge in Humpolec, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "synagoga v Humpolci", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "synagoga v Humpolci", "description": "Synagoge in Okres Pelhřimov, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "synagoga v Humpolci", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagoga v Humpolci", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "synagoga v Humpolci", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Vodní nádrž Sedlice', 'Přehradní nádrž vybudovaná v letech 1921–1927 na řece Želivce pod soutokem říčky Hejlovky a Jankovského potoka, zhruba 7 km jihozápadně od Humpolce. Její hráz je od roku 2012 kulturní památkou České republiky. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.51389, 15.26944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Sedlice.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Sedlice.jpg"}'::text[], 3, '{"en": {"name": "Sedlice Reservoir", "description": "Lake in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Sedlice", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodní nádrž Sedlice", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Sedlice", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Sedlice", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Sedlice", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodní nádrž Sedlice", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
